package grc20helper

import (
	"gno.land/r/demo/defi/grc20reg"
)

func GetName(tokenKey string) string {
	return grc20reg.MustGet(tokenKey).GetName()
}

func GetSymbol(tokenKey string) string {
	return grc20reg.MustGet(tokenKey).GetSymbol()
}

func GetDecimals(tokenKey string) int {
	return grc20reg.MustGet(tokenKey).GetDecimals()
}

func TotalSupply(tokenKey string) int64 {
	return grc20reg.MustGet(tokenKey).TotalSupply()
}

func BalanceOf(tokenKey string, account address) int64 {
	return grc20reg.MustGet(tokenKey).BalanceOf(account)
}

func Allowance(tokenKey string, owner, spender address) int64 {
	return grc20reg.MustGet(tokenKey).Allowance(owner, spender)
}

// Transfer moves tokens owned by the immediate caller. A direct user call
// spends the user's balance; a realm cross-call spends the calling realm's.
func Transfer(cur realm, tokenKey string, to address, amount int64) {
	checkErr(grc20reg.MustGet(tokenKey).CallerTeller().Transfer(0, cur, to, amount))
}

// Approve sets an allowance owned by the immediate caller. A direct user call
// uses the user's allowance; a realm cross-call uses the calling realm's.
func Approve(cur realm, tokenKey string, spender address, amount int64) {
	checkErr(grc20reg.MustGet(tokenKey).CallerTeller().Approve(0, cur, spender, amount))
}

// TransferFrom spends an allowance as the immediate caller. A direct user is
// the spender; for a realm cross-call, the calling realm is the spender.
func TransferFrom(cur realm, tokenKey string, from, to address, amount int64) {
	checkErr(grc20reg.MustGet(tokenKey).CallerTeller().TransferFrom(0, cur, from, to, amount))
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

package grc20helper

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strings"

	"gno.land/p/demo/tokens/grc20"
	"gno.land/p/jeronimoalbi/mdform"
	"gno.land/p/moul/md"
	"gno.land/p/nt/avl/v0/pager"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/demo/defi/grc20reg"
)

var (
	// chainDomain prefixes realm package paths; gnoweb URLs omit it.
	chainDomain = runtime.ChainDomain()

	// realmPath is this realm's own package path, captured at init time. It is
	// read here rather than inside Render because unsafe.CurrentRealm() follows
	// the calling realm, which is not necessarily this one.
	realmPath = unsafe.CurrentRealm().PkgPath()
)

// pageSize is how many registered tokens a listing page shows. The registry is
// an AVL tree keyed by "<realm path>.<symbol>", so listings are in
// lexicographic key order — the registry records no registration time or
// sequence, so "most recently registered" cannot be derived on-chain.
const pageSize = 20

// Render lists registered tokens when path is empty, and shows a single
// token's metadata plus a transfer form when path is a token key.
//
//	""                              -> token list (20 per page, ?page=N)
//	"gno.land/r/demo/foo20.FOO"     -> token detail + transfer form
func Render(path string) string {
	key, _ := splitQuery(path)
	if key == "" {
		return renderList(path)
	}

	return renderToken(key)
}

func renderList(path string) string {
	p := pager.NewPager(grc20reg.GetRegistry(), pageSize, false)
	page := p.MustGetPageByPath(path)

	out := md.H1("GRC20 Helper")
	out += "Flat GRC20 calls keyed by the " + md.Link("grc20reg", "/r/demo/defi/grc20reg") +
		" registry key.\n\n"

	if page.TotalItems == 0 {
		return out + md.Blockquote("No registered token.")
	}

	out += ufmt.Sprintf("%d registered token(s), sorted by key.\n\n", page.TotalItems)

	items := make([]string, 0, len(page.Items))
	for _, item := range page.Items {
		token, ok := item.Value.(*grc20.Token)
		if !ok {
			continue
		}
		items = append(items, ufmt.Sprintf(
			"%s (%s) — %s",
			md.Link(md.EscapeText(token.GetName()), tokenURL(item.Key)),
			md.EscapeText(token.GetSymbol()),
			md.InlineCode(item.Key),
		))
	}
	out += md.BulletList(items)

	if picker := page.Picker(path); picker != "" {
		out += "\n" + md.HorizontalRule() + picker + "\n"
	}
	return out
}

func renderToken(key string) string {
	token := grc20reg.Get(key)
	if token == nil {
		return md.H1("Unknown token") +
			md.Blockquote("No token registered under "+md.InlineCode(key)+".") +
			"\n" + md.Link("← Back to the token list", listURL()) + "\n"
	}

	out := md.H1(md.EscapeText(token.GetName()))
	out += md.BulletList([]string{
		"symbol: " + md.Bold(md.EscapeText(token.GetSymbol())),
		"decimals: " + ufmt.Sprintf("%d", token.GetDecimals()),
		"total supply: " + ufmt.Sprintf("%d", token.TotalSupply()),
		"registry key: " + md.InlineCode(key),
	})

	out += "\n" + md.H2("Transfer")
	out += md.Blockquote(
		"Submitting shows a `gnokey maketx call` command to copy and run — " +
			"gnoweb does not broadcast the transaction for you.")
	out += "\n" + transferForm(key)

	out += "\n" + md.Link("← Back to the token list", listURL()) + "\n"

	return out
}

// transferForm builds the inline form for Transfer.
//
// Form fields map to call arguments BY ORDER, not by name, and the leading
// `cur realm` parameter is never passed as an argument — so the fields must be
// exactly tokenKey, to, amount, in that order.
func transferForm(key string) string {
	form := mdform.New("exec", "Transfer")
	form.Input("tokenKey",
		"placeholder", "Registry key",
		"value", key,
		"readonly", "true",
		"required", "true",
	)
	form.Input("to",
		"placeholder", "g1... recipient address",
		"description", "Recipient address",
		"required", "true",
	)
	form.Input("amount",
		"type", mdform.InputTypeNumber,
		"placeholder", "Amount in base units",
		"description", "Amount, in base units (not adjusted for decimals)",
		"required", "true",
	)
	return form.String()
}

// listURL is the absolute gnoweb path of this realm's token list, and tokenURL
// the path of a single token's subpage.
//
// The path is taken from realmPath rather than from the calling realm: Render
// must always link back to this realm, whoever invoked it. Absolute paths
// matter because a relative ":key" link resolves against the browser's current
// URL, which already carries a token key once a subpage is open.
func listURL() string {
	return strings.TrimPrefix(realmPath, chainDomain)
}

func tokenURL(key string) string {
	return listURL() + ":" + key
}

// splitQuery splits a render path into its path and query string parts.
func splitQuery(path string) (string, string) {
	for i := 0; i < len(path); i++ {
		if path[i] == '?' {
			return path[:i], path[i+1:]
		}
	}
	return path, ""
}

package grc20helper

import (
	"strings"
	"testing"

	"gno.land/p/demo/tokens/grc20"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/demo/defi/grc20reg"
)

// The listing must always report the registry's own total, whatever seeded it.
func TestRenderListHeader(t *testing.T) {
	size := grc20reg.GetRegistry().Size()
	got := Render("")

	if size == 0 {
		if !strings.Contains(got, "No registered token.") {
			t.Errorf("expected empty-registry notice, got:\n%s", got)
		}
		return
	}

	want := ufmt.Sprintf("%d registered token(s)", size)
	if !strings.Contains(got, want) {
		t.Errorf("expected %q in listing, got:\n%s", want, got)
	}
}

func TestRenderUnknownToken(t *testing.T) {
	got := Render("gno.land/r/demo/nope.NOPE")
	if !strings.Contains(got, "Unknown token") {
		t.Errorf("expected unknown-token notice, got:\n%s", got)
	}
}

func TestRenderTokenDetail(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/onbloc/testfoo"))
	token, ledger := grc20.NewToken("Foo Token", "FOO", 6, 0, cur)
	ledger.Mint(cur.Address(), 1234567)
	key := grc20reg.Register(cross(cur), token, "")

	list := Render("")
	if !strings.Contains(list, "Foo Token") {
		t.Errorf("list missing token name:\n%s", list)
	}
	if !strings.Contains(list, key) {
		t.Errorf("list missing registry key %q:\n%s", key, list)
	}

	// Each entry must link to this realm's subpage for the token, using an
	// absolute path — not to the caller's realm, and not relative.
	wantLink := "(/r/onbloc/utils/grc20helper:" + key + ")"
	if !strings.Contains(list, wantLink) {
		t.Errorf("list missing subpage link %q:\n%s", wantLink, list)
	}

	detail := Render(key)
	for _, want := range []string{
		"# Foo Token",
		"symbol: **FOO**",
		"decimals: 6",
		"total supply: 1234567",
		`<gno-form exec="Transfer">`,
		`<gno-input name="tokenKey"`,
		`<gno-input name="to"`,
		`<gno-input name="amount"`,
	} {
		if !strings.Contains(detail, want) {
			t.Errorf("detail missing %q:\n%s", want, detail)
		}
	}

	// The transfer form's fields map to arguments by order, and `cur realm` is
	// never one of them, so the order must stay tokenKey, to, amount.
	iKey := strings.Index(detail, `name="tokenKey"`)
	iTo := strings.Index(detail, `name="to"`)
	iAmount := strings.Index(detail, `name="amount"`)
	if !(iKey < iTo && iTo < iAmount) {
		t.Errorf("transfer form fields out of order: tokenKey=%d to=%d amount=%d", iKey, iTo, iAmount)
	}
}

// Registering more than pageSize tokens must split the listing into pages.
// The registry is shared across tests in this package, so page sizes are
// checked against its actual total rather than against the count added here.
func TestRenderPaging(cur realm, t *testing.T) {
	for i := 0; i < pageSize+5; i++ {
		suffix := ufmt.Sprintf("%02d", i)
		testing.SetRealm(testing.NewCodeRealm("gno.land/r/onbloc/tk" + suffix))
		token, ledger := grc20.NewToken("Token "+suffix, "TK"+suffix, 6, 0, cur)
		ledger.Mint(cur.Address(), 1000)
		grc20reg.Register(cross(cur), token, "")
	}

	total := grc20reg.GetRegistry().Size()
	if total <= pageSize {
		t.Fatalf("test needs more than %d tokens to page, got %d", pageSize, total)
	}

	page1 := Render("")
	if n := strings.Count(page1, "- ["); n != pageSize {
		t.Errorf("page 1 should list %d items, got %d", pageSize, n)
	}
	if !strings.Contains(page1, "?page=2") {
		t.Errorf("page 1 missing pager link:\n%s", page1)
	}

	// The last page holds the remainder; a full division means a full page.
	wantLast := total % pageSize
	if wantLast == 0 {
		wantLast = pageSize
	}
	lastPage := total / pageSize
	if total%pageSize != 0 {
		lastPage++
	}

	got := Render(ufmt.Sprintf("?page=%d", lastPage))
	if n := strings.Count(got, "- ["); n != wantLast {
		t.Errorf("page %d should list %d items, got %d", lastPage, wantLast, n)
	}
}

package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1n68pkpxxd8klsdv8c3pmu6h9t0uys7fkpspau0"), 5),
			valv3.NewValoperChange(address("g1x4n02j4q9pk6mp5gpz5ags4ta2kvq4du9k6wmc"), 5),
		},
		"Add 2 validator(s) to the valset",
		"Batch-add 2 operator(s) to the active valset with voting power 5.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}
